235	  });
236	
237	  // Refs: one options input / one for-<Entity> method per target, so names stay unambiguous.
238	  const manyTargets = new Set();
239	  s.fields.forEach((f, i) => {
240	    if (f.type !== 'ref') return;
241	    if (f.ref.entity === s.entity) add(['fields', i, 'ref', 'entity'], 'a self reference is not supported');
242	    if (f.many) {
243	      if (manyTargets.has(f.ref.entity)) add(['fields', i, 'ref', 'entity'], 'two many refs to the same entity are not supported');
