254	  } else if (s.manage) {
255	    add(['manage'], 'is only allowed when kinds includes manage');
256	  }
257	
258	  if (s.manage) {
259	    const m = s.manage;
260	    const lookup = (name, path, accept, what) => {
261	      const f = byName.get(name);
262	      if (!f) add(path, `"${name}" is not a declared field`);
263	      else if (!accept.includes(f.type)) add(path, `"${name}" must be a ${what} field`);
264	      return f;
265	    };
266	    const seenCols = new Set();
267	    m.columns.forEach((c, i) => {
268	      if (seenCols.has(c.field)) add(['manage', 'columns', i, 'field'], 'duplicate column');
269	      seenCols.add(c.field);
270	      const f = lookup(c.field, ['manage', 'columns', i, 'field'], i === 0 ? ['string', 'text'] : ['string', 'text', 'number', 'boolean', 'enum', 'date'], i === 0 ? 'string or text (the first column is the row title)' : 'string, text, number, boolean, enum or date');
271	      if (c.badge) {
272	        if (f && f.type !== 'enum') add(['manage', 'columns', i, 'badge'], 'a badge needs an enum field');
273	        if (f && f.type === 'enum') {
274	          for (const v of Object.keys(c.badge.variants)) {
275	            if (!f.options.includes(v)) add(['manage', 'columns', i, 'badge', 'variants', v], 'is not an option of the field');
276	          }
277	        }
278	      }
279	    });
280	    const seenSearch = new Set();
281	    m.search.forEach((n, i) => {
282	      if (seenSearch.has(n)) add(['manage', 'search', i], 'duplicate search field');
283	      seenSearch.add(n);
284	      const sf = lookup(n, ['manage', 'search', i], ['string', 'text'], 'string or text');
285	      if (sf && !sf.inForm) add(['manage', 'search', i], 'must be a field with inForm true');
286	    });
287	    const seenFilters = new Set();
288	    (m.filters ?? []).forEach((flt, i) => {
289	      const path = ['manage', 'filters', i];
290	      if (flt.control === 'select') {
291	        lookup(flt.field, [...path, 'field'], ['enum'], 'enum');
292	      } else {
293	        const f = lookup(flt.field, [...path, 'field'], ['enum', 'boolean'], 'enum or boolean');
294	        if (f && !f.inForm) add([...path, 'field'], 'must be a field with inForm true');
295	        if (f && f.type === 'enum') {
296	          if (flt.value === undefined) add([...path, 'value'], 'is required for an enum filter');
297	          else if (!f.options.includes(flt.value)) add([...path, 'value'], 'is not an option of the field');
298	        }
299	        if (f && f.type === 'boolean' && flt.value !== undefined) add([...path, 'value'], 'is not allowed for a boolean filter');
300	      }
301	      if (seenFilters.has(flt.field)) add([...path, 'field'], 'must not repeat a filtered field');
302	      seenFilters.add(flt.field);
303	    });
304	    if (m.sort) lookup(m.sort.field, ['manage', 'sort', 'field'], ['string', 'text', 'number', 'date', 'enum'], 'string, text, number, date or enum');
305	  }
306	
307	  if (s.examples) {
308	    s.examples.forEach((row, ri) => {
309	      const known = new Set(s.fields.map((f) => f.name));
310	      for (const key of Object.keys(row)) {
311	        if (!known.has(key)) add(['examples', ri, key], 'is not a declared field');
312	      }
313	      s.fields.forEach((f) => {
314	        if (!(f.name in row)) {
315	          add(['examples', ri, f.name], 'is missing');
316	          return;
317	        }
318	        const msg = checkValue(f, row[f.name]);
319	        if (msg) add(['examples', ri, f.name], msg);
320	      });
321	    });
322	  }
323	});
324	
325	/**
326	 * Parse a spec, returning the validated value or a list of readable problems.
327	 * @param {unknown} data
328	 * @returns {{ ok: true, spec: any } | { ok: false, errors: string[] }}
329	 */
330	function parseSpec(data) {
331	  const result = spec.safeParse(data);
332	  if (result.success) return { ok: true, spec: result.data };
333	  const errors = result.error.issues.map((issue) => {
334	    const where = issue.path.length ? issue.path.join('.') : '(spec)';
335	    return `${where}: ${issue.message}`;
336	  });
337	  return { ok: false, errors };
338	}
339	
340	module.exports = { spec, parseSpec, SAFE_TEXT_PATTERN, BADGE_VARIANTS, KINDS };
